// Description: C header of the i2c_master register map (generated by regmap_gen.py): byte offsets, reset values,
//   field shifts and masks.
// Date: 2026-10-16
#ifndef I2C_MASTER_REGS_H
#define I2C_MASTER_REGS_H
#define I2C_MASTER_REGS_ID_OFFSET 0x00u
#define I2C_MASTER_REGS_VERSION_OFFSET 0x04u
#define I2C_MASTER_REGS_DATE_OFFSET 0x08u
#define I2C_MASTER_REGS_ID_VALUE 0x4932434Du   /* "I2CM" */
#define I2C_MASTER_REGS_CTRL_OFFSET 0x10u   /* CMD */
#define I2C_MASTER_REGS_CTRL_RESET 0x00000000u
#define I2C_MASTER_REGS_CTRL_EN_SHIFT 0u
#define I2C_MASTER_REGS_CTRL_EN_MASK 0x00000001u
#define I2C_MASTER_REGS_CTRL_START_SHIFT 1u
#define I2C_MASTER_REGS_CTRL_START_MASK 0x00000002u
#define I2C_MASTER_REGS_CTRL_READ_SHIFT 2u
#define I2C_MASTER_REGS_CTRL_READ_MASK 0x00000004u
#define I2C_MASTER_REGS_CTRL_NO_STOP_SHIFT 3u
#define I2C_MASTER_REGS_CTRL_NO_STOP_MASK 0x00000008u
#define I2C_MASTER_REGS_ADDR_OFFSET 0x14u   /* RW */
#define I2C_MASTER_REGS_ADDR_RESET 0x00000000u
#define I2C_MASTER_REGS_LEN_OFFSET 0x18u   /* RW */
#define I2C_MASTER_REGS_LEN_RESET 0x00000000u
#define I2C_MASTER_REGS_DIV_OFFSET 0x1Cu   /* RW */
#define I2C_MASTER_REGS_STATUS_OFFSET 0x20u   /* CMD */
#define I2C_MASTER_REGS_STATUS_RESET 0x00000000u
#define I2C_MASTER_REGS_STATUS_BUSY_SHIFT 0u
#define I2C_MASTER_REGS_STATUS_BUSY_MASK 0x00000001u
#define I2C_MASTER_REGS_STATUS_DONE_SHIFT 1u
#define I2C_MASTER_REGS_STATUS_DONE_MASK 0x00000002u
#define I2C_MASTER_REGS_STATUS_NACK_SHIFT 2u
#define I2C_MASTER_REGS_STATUS_NACK_MASK 0x00000004u
#define I2C_MASTER_REGS_STATUS_ARB_LOST_SHIFT 3u
#define I2C_MASTER_REGS_STATUS_ARB_LOST_MASK 0x00000008u
#define I2C_MASTER_REGS_STATUS_RX_LEVEL_SHIFT 16u
#define I2C_MASTER_REGS_STATUS_RX_LEVEL_MASK 0xFFFF0000u
#endif /* I2C_MASTER_REGS_H */
